class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.size = 0
        self.key_to_node = {}  # key -> Node
        self.freq_to_keys = {}  # freq -> set of keys
        self.min_freq = 0

    class Node:
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.freq = 1
            self.prev = None
            self.next = None

    def _remove_node(self, node):
        prev_node = node.prev
        next_node = node.next
        if prev_node:
            prev_node.next = next_node
        if next_node:
            next_node.prev = prev_node
        if node == self.key_to_node.get(node.key).next:
            self.key_to_node[node.key] = None

    def _add_to_head(self, node):
        head = self.key_to_node.get(node.key).next
        node.next = head
        node.prev = head.prev
        if head.prev:
            head.prev.next = node
        head.prev = node

    def _remove_from_head(self):
        head = self.key_to_node.get(None).next
        self._remove_node(head)
        return head

    def _update_freq(self, node):
        key = node.key
        freq = node.freq
        self.key_to_node[key] = None
        self._remove_node(node)
        node.freq += 1
        self._add_to_head(node)
        if freq in self.freq_to_keys:
            self.freq_to_keys[freq].discard(key)
            if not self.freq_to_keys[freq]:
                del self.freq_to_keys[freq]
                if freq == self.min_freq:
                    self.min_freq += 1

    def get(self, key: int) -> int:
        if key not in self.key_to_node:
            return -1
        node = self.key_to_node[key]
        self._update_freq(node)
        return node.value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.key_to_node:
            node = self.key_to_node[key]
            node.value = value
            self._update_freq(node)
        else:
            if self.size >= self.capacity:
                lru_node = self._remove_from_head()
                if lru_node:
                    key_to_remove = lru_node.key
                    del self.key_to_node[key_to_remove]
                    freq = lru_node.freq
                    self.freq_to_keys[freq].discard(key_to_remove)
                    if not self.freq_to_keys[freq]:
                        del self.freq_to_keys[freq]
                    self.size -= 1
            node = self.Node(key, value)
            self.key_to_node[key] = node
            self.freq_to_keys[1].add(key)
            if 1 not in self.freq_to_keys:
                self.freq_to_keys[1] = set()
            self.min_freq = 1
            self.size += 1

