def lis_length(a):
    if not a:
        return 0

    n = len(a)
    tails = []

    for x in a:
        # Use binary search to find the insertion point
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < x:
                left = mid + 1
            else:
                right = mid

        # If x is greater than all elements in tails, append it
        if left == len(tails):
            tails.append(x)
        else:
            # Otherwise, replace the first element >= x with x
            tails[left] = x

    return len(tails)
