import re

def parse_duration(s):
    if not s:
        raise ValueError("Empty duration string")

    if s.startswith('-'):
        negative = True
        s = s[1:]
    else:
        negative = False

    # Pattern to match ISO 8601 duration components
    # P[nY][nM][nDT[nH][nM][nS]]
    pattern = r'^P(?:(\d+)Y)?(?:(\d+)M)?(?:(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+(?:\.\d+)?)S)?)?)$'
    match = re.match(pattern, s)

    if not match:
        raise ValueError(f"Invalid duration format: {s}")

    years = int(match.group(1) or 0)
    months = int(match.group(2) or 0)
    days = int(match.group(3) or 0)
    hours = int(match.group(4) or 0)
    minutes = int(match.group(5) or 0)
    seconds_str = match.group(6)

    if seconds_str is None:
        if years == 0 and months == 0 and days == 0 and hours == 0 and minutes == 0:
            raise ValueError("At least one duration field must be present")
        total_seconds = 0.0
    else:
        seconds = float(seconds_str)
        total_seconds = seconds
        if minutes > 0:
            total_seconds += minutes * 60.0
        if hours > 0:
            total_seconds += hours * 3600.0
        if days > 0:
            total_seconds += days * 86400.0
        if months > 0:
            total_seconds += months * 30 * 86400.0
        if years > 0:
            total_seconds += years * 365 * 86400.0

    if negative:
        total_seconds = -total_seconds

    return total_seconds
