from typing import List, Tuple, Optional, Union

def parse_field(field: str, min_val: int, max_val: int) -> List[int]:
    """Parse a single cron field into a sorted list of integers."""
    if not field:
        raise ValueError("Empty field")

    parts = field.split(',')
    result = set()

    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError("Empty part in field")

        if part == '*':
            result.update(range(min_val, max_val + 1))
        elif '/' in part:
            base, step = part.split('/')
            step = int(step)
            if step <= 0:
                raise ValueError(f"Step must be positive: {step}")
            if base == '*':
                start = min_val
                end = max_val
            elif '-' in base:
                start, end = map(int, base.split('-'))
                if start < min_val or end > max_val or start > end:
                    raise ValueError(f"Invalid range in step: {base}")
            else:
                start = int(base)
                end = max_val
            for i in range(start, end + 1, step):
                if min_val <= i <= max_val:
                    result.add(i)
        elif '-' in part:
            start, end = map(int, part.split('-'))
            if start < min_val or end > max_val or start > end:
                raise ValueError(f"Invalid range: {part}")
            result.update(range(start, end + 1))
        else:
            val = int(part)
            if val < min_val or val > max_val:
                raise ValueError(f"Value out of range: {val}")
            result.add(val)

    return sorted(result)

def parse_cron(expr: str) -> Tuple[List[int], List[int], List[int], List[int], List[int]]:
    """Parse a 5-field cron expression."""
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute = parse_field(fields[0], 0, 59)
    hour = parse_field(fields[1], 0, 23)
    day_of_month = parse_field(fields[2], 1, 31)
    month = parse_field(fields[3], 1, 12)
    day_of_week = parse_field(fields[4], 0, 6)

    return minute, hour, day_of_month, month, day_of_week

def is_valid_date(year: int, month: int, day: int) -> bool:
    """Check if a date is valid."""
    try:
        datetime(year, month, day)
        return True
    except ValueError:
        return False

def next_fire(expr: str, after: datetime) -> datetime:
