    # Determine if day-of-month and day-of-week are both restricted
    dom_restricted = day_of_month != list(range(1, 32))
    dow_restricted = day_of_week != list(range(0, 7))

    # Start searching from the next minute
    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # We need to search forward. To avoid infinite loops, we'll search for a reasonable period.
    # Cron expressions can be complex, but we can search year by year.
    # Start from current year, move forward until we find a match.

    year = current.year
    while True:
