        for m in range(1, 13):
            if m not in month:
                continue

            # Determine the days to check for this month
            if dom_restricted and dow_restricted:
                # Both restricted: fire if day matches EITHER
                days_to_check = []
                for d in range(1, 32):
                    if d in day_of_month or d in day_of_week:
                        if is_valid_date(year, m, d):
                            days_to_check.append(d)
            elif dom_restricted:
