class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.snapshots = []
        self.snapshot_count = 0

    def find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        return root

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a == root_b:
            return False

        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a

        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]

        self.history.append((root_b, root_a, self.size[root_a]))
        return True

    def snapshot(self):
        self.snapshots.append(len(self.history))
        return self.snapshot_count
        self.snapshot_count += 1

    def rollback(self, token):
        target = self.snapshots[token]
        while len(self.history) > target:
            _, root_a, old_size = self.history.pop()
            root_b = self.parent[root_a]
            self.parent[root_a] = root_a
            self.parent[root_b] = root_b
            self.size[root_a] = old_size - self.size[root_b]
            self.size[root_b] = 1

    def components(self):
        return sum(1 for i in range(len(self.parent)) if self.parent[i] == i)

