    def __init__(self):
        self.root = {}
        self.word_count = {}  # Maps word -> count to handle duplicates

    def add(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['$'] = node.get('$', 0) + 1
        self.word_count[word] = self.word_count.get(word, 0) + 1

    def remove(self, word: str) -> bool:
        if word not in self.word_count:
            return False
        if self.word_count[word] == 0:
            return False

        self.word_count[word] -= 1
        if self.word_count[word] == 0:
            del self.word_count[word]

        node = self.root
        for char in word:
            if char not in node:
                return False
            node = node[char]
        if '$' not in node:
            return False
        node['$'] -= 1
        if node['$'] == 0:
            del node['$']
        return True

    def search(self, pattern: str) -> list:
        results = []
        self._search_helper(self.root, pattern, 0, [], results)
        return sorted(results)

    def _search_helper(self, node, pattern, idx, current_path, results):
        if idx == len(pattern):
            if '$' in node and node['$'] > 0:
                results.append("".join(current_path))
            return

