        if char == '.':
            for key, value in node.items():
                if key != '$':
                    current_path.append(key)
                    self._search_helper(value, pattern, idx + 1, current_path, results)
                    current_path.pop()
        else:
            if char in node:
                current_path.append(char)
                self._search_helper(node[char], pattern, idx + 1, current_path, results)
                current_path.pop()

