import threading

def transfer_all(accounts, ops):
    n = len(accounts)
    locks = [threading.Lock() for _ in range(n)]

    def do_transfer(src, dst, amount):
        if src < 0 or dst < 0 or src >= n or dst >= n:
            return
        if src == dst:
            return

        # Acquire locks in sorted order of account indices to prevent deadlock
        if src < dst:
            lock1, lock2 = locks[src], locks[dst]
        else:
            lock1, lock2 = locks[dst], locks[src]

        with lock1:
            with lock2:
                if accounts[src] >= amount:
                    accounts[src] -= amount
                    accounts[dst] += amount

    threads = []
    for src, dst, amount in ops:
        t = threading.Thread(target=do_transfer, args=(src, dst, amount))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return accounts
