module.exports = function deepMerge(target, ...sources) {
  if (!sources.length) return target;

  const result = {};
  const keys = new Set();

  // Collect all keys from target and sources
  for (const source of [target, ...sources]) {
    if (source && typeof source === 'object' && !Array.isArray(source)) {
      for (const key of Object.keys(source)) {
        keys.add(key);
      }
    }
  }

  // Filter out dangerous keys to prevent prototype pollution
  const safeKeys = Array.from(keys).filter(key => {
    return key !== '__proto__' && key !== 'constructor' && key !== 'prototype';
  });

  for (const key of safeKeys) {
    let targetValue = target[key];
    let sourceValue = null;

    // Find the first non-null source value for this key
    for (const source of sources) {
      if (source && source[key] !== null) {
        sourceValue = source[key];
        break;
      }
    }

    // If no non-null source value exists, skip (undefined doesn't overwrite)
    if (sourceValue === null) continue;

    // Check if both are plain objects
    const isTargetPlain = targetValue !== null && typeof targetValue === 'object' && !Array.isArray(targetValue);
    const isSourcePlain = sourceValue !== null && typeof sourceValue === 'object' && !Array.isArray(sourceValue);

    if (isTargetPlain && isSourcePlain) {
      // Recursively merge
      result[key] = deepMerge({}, targetValue, sourceValue);
    } else {
      // Replace: arrays, primitives, Date, etc.
      // Note: Non-plain objects like Date are copied by reference as per requirement
      result[key] = sourceValue;
    }
  }

  return result;
};

