export type Config = {
  name: string;
  age?: number;
  active: boolean;
};

export interface BuilderState<T extends Record<string, unknown>> {
  data: Partial<T>;
  requiredKeys: Set<keyof T>;
  optionalKeys: Set<keyof T>;
}

export function builder<Config extends Record<string, unknown>>(
  _config: Config
): Builder<Config> {
  const requiredKeys = new Set<keyof Config>(
    Object.keys(_config).filter((k) => {
      const prop = _config[k as keyof Config];
      return prop !== undefined && prop !== null;
    })
  );

  const optionalKeys = new Set<keyof Config>(
    Object.keys(_config).filter((k) => {
      const prop = _config[k as keyof Config];
      return prop === undefined || prop === null;
    })
  );

  const state: BuilderState<Config> = {
    data: {} as Partial<Config>,
    requiredKeys,
    optionalKeys,
  };

  return {
    set: <K extends keyof Config>(key: K, value: Config[K]) => {
      if (!state.requiredKeys.has(key) && !state.optionalKeys.has(key)) {
        throw new Error(`Unknown key: ${key}`);
      }
      state.data[key] = value;
      return builder<Config>(_config);
    },
    build: () => {
      const missingRequired = Array.from(state.requiredKeys).filter(
        (k) => state.data[k as keyof Config] === undefined
      );

      if (missingRequired.length > 0) {
        throw new Error(`Missing required keys: ${missingRequired.join(', ')}`);
      }

      return state.data as Config;
    },
  };
}

export type Builder<Config extends Record<string, unknown>> = {
  set<K extends keyof Config>(key: K, value: Config[K]): Builder<Config>;
  build(): Config;
};

