export type RouteParams<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer Name}` ? Name : never;
}[keyof T];

export type RouteFn<T extends Record<string, string>> = T extends never
  ? () => string
  : <P extends RouteParams<T>>(params: P) => string;

export function defineRoutes<T extends Record<string, string>>(
  routes: T
): {
  [K in keyof T]: T[K] extends `:${infer Params}`
    ? Params extends `${infer P1}:${infer P2}`
      ? RouteFn<{ P1: P1; P2: P2 }>
      : Params extends `${infer P}`
        ? RouteFn<{ P: P }>
        : RouteFn<never>
    : T[K] extends string
      ? RouteFn<never>
      : never;
} {
  const result: any = {};

  for (const [name, path] of Object.entries(routes)) {
    const paramRegex = /:(\w+)/g;
    const matches = [...path.matchAll(paramRegex)];
    const paramNames = matches.map((m) => m[1]);
    const paramMap = new Map(paramNames.map((n, i) => [n, i]));

    const fn = (params: Record<string, string>) => {
      if (paramNames.length === 0) {
        return path;
      }

      const keys = Object.keys(params);
      if (keys.length !== paramNames.length) {
        throw new Error(
          `Route '${name}' expects ${paramNames.length} params, got ${keys.length}`
        );
      }

      for (const key of keys) {
        if (!paramMap.has(key)) {
          throw new Error(`Route '${name}' does not accept param '${key}'`);
        }
      }

      let resultPath = path;
      for (const [key, index] of paramMap.entries()) {
        resultPath = resultPath.replace(`:${key}`, params[key]);
      }
      return resultPath;
    };

    result[name] = fn as any;
  }

  return result;
}

